        mesh->vertices[0] = *(ShadowInt64Pair *)((char *)vertexBase + quadPtr->vertexOffset0);
        mesh->vertices[1] = *(ShadowInt64Pair *)((char *)vertexBase + quadPtr->vertexOffset1);
