        mesh->vertices[3] = *(ShadowInt64Pair *)((char *)vertexBase + quadPtr->vertexOffset3);
        StoreDeferredDrawArgs(&mesh->vertices[0], &mesh->vertices[1], &mesh->vertices[2]);
        ApplyDeferredDrawArgs();
        faigaQuad->tag = faigaQuad->tag & 0xFFFFFF | 0x9000000;
        faigaQuad->flags = quadPtr->flags | mesh->packedBits;
        faigaQuad->uv0Clut = quadPtr->uv0Clut;
        faigaQuad->uv2 = quadPtr->uv2;
        faigaQuad->uv3 = quadPtr->uv3;
