/*
 * Task animating a growing and fading 3D model for Faiga3.
 */
// FUNCTION: FF7 0x0056e65a
void __cdecl BattleFx_MagicFire3MultiGrowingFadeModelTask(void)
{
#pragma pack(push, 1)
    /* Locals by stack slot: see FRAME UNION in lib/codegen.h. */
    union {
        unsigned char storage[64];
        SVECTOR rotX;
        struct { unsigned char pad_to_8[0x8]; BattleFxFire3MultiGrowingFadeModelSlot *slot; };
        struct { unsigned char pad_to_C[0xC]; PsxMatrix rotMatrix; };
        struct { unsigned char pad_to_2C[0x2C]; BattleFxModelDraw *drawModel; };
        struct { unsigned char pad_to_30[0x30]; VECTOR scaleArg; };
    } frame;
#pragma pack(pop)

    frame.slot = (BattleFxFire3MultiGrowingFadeModelSlot *)BATTLE_CURRENT_TASK_SLOT;
    frame.rotX.vx = 0xFC00;
    frame.rotX.vy = 0;
    frame.rotX.vz = 0;
    RotMatrixXYZ(&frame.rotX, &frame.rotMatrix);
    frame.rotMatrix.t[0] = frame.slot->posX;
    frame.rotMatrix.t[1] = 0;
    frame.rotMatrix.t[2] = frame.slot->posZ;
    frame.scaleArg.vz = frame.slot->scale;
    frame.scaleArg.vy = frame.scaleArg.vz;
    frame.scaleArg.vx = frame.scaleArg.vy;
    ScaleMatrix(&frame.rotMatrix, &frame.scaleArg);
    MultiplyMatrix(&g_BattleCameraTransform, &frame.rotMatrix, &frame.rotMatrix);
    SetRotMatrix(&frame.rotMatrix);
    SetTransMatrix(&frame.rotMatrix);
    frame.drawModel = (BattleFxModelDraw *)Gfx_GetPsxScratchpadPtr(0);
    frame.drawModel->modelGroup = Gfx_ModelTableGetRenderObject(3, g_BattleMagicFire3MultiLoadedRes);
    frame.drawModel->flags = 0x88;
    frame.drawModel->uvScroll = 0;
    frame.drawModel->stateFlags = 0;
    frame.drawModel->texturePageBits = 0;
    if (frame.slot->frameCounter < 6) {
        frame.drawModel->fadeLevel = 0x1000 - frame.slot->frameCounter * 0x255;
    } else if (frame.slot->frameCounter >= 0xC) {
        frame.drawModel->fadeLevel = (frame.slot->frameCounter - 0xC) * 0x12A;
    } else {
        frame.drawModel->fadeLevel = 0x200;
    }
    SetDrawColorRGB(0, 0, 0);
    g_BattleFxActiveDrawListPtr = BattleFx_SubmitModelDraw((BattleFxModelDraw *)frame.drawModel, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleFxActiveDrawListPtr);
    if (frame.slot->frameCounter >= 0x18) {
        frame.slot->ownerSlot = BATTLE_TASK_FREE;
    }
    if (g_BattleIsPaused != 0) {
        return;
    }
    frame.slot->scale += frame.slot->scaleStep;
    (frame.slot->frameCounter)++;
}

/*
 * Task animating a flashing 3D model effect for Faiga3.
 */
// FUNCTION: FF7 0x0056e81e
void __cdecl BattleFx_MagicFire3MultiFlashModelTask(void)
{
    int p, q;
    BattleFxModelDraw *modelPtr;
    int s, t, u, v, w;
    BattleFxFire3MultiFlash *slotPtr;
    int y, z, a, b, c, d, e;

    slotPtr = (BattleFxFire3MultiFlash *)BATTLE_CURRENT_TASK_SLOT;
    BattleFx_InstallBillboardMatrix((short *)&slotPtr->pos, (short)slotPtr->size, -(slotPtr->size >> 3));
    modelPtr = (BattleFxModelDraw *)Gfx_GetPsxScratchpadPtr(0);
    modelPtr->modelGroup = Gfx_ModelTableGetRenderObject(2, g_BattleMagicFire3MultiLoadedRes);
    modelPtr->flags = 0x88;
    modelPtr->uvScroll = 0;
    modelPtr->fadeLevel = 0;
    modelPtr->stateFlags = 0;
    modelPtr->texturePageBits = 0;
    g_BattleFxActiveDrawListPtr = BattleFx_SubmitModelDraw((BattleFxModelDraw *)modelPtr, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleFxActiveDrawListPtr);
    if (slotPtr->phase >= 0xC) {
        slotPtr->ownerSlot = BATTLE_TASK_FREE;
    }
    if (g_BattleIsPaused != 0) {
        return;
    }
    /* Numeric pillar timeline tick index (0..11). */
    switch (slotPtr->phase) {
    case BATTLE_FIRE3_TICK_SHRINK_0:
    case BATTLE_FIRE3_TICK_SHRINK_1:
        slotPtr->size -= slotPtr->shrinkStep;
        break;
    case BATTLE_FIRE3_TICK_FLASH_START_1:
        BattleFx_StartScreenFlashRamp(1);
        slotPtr->size -= slotPtr->shrinkStep;
        break;
    case BATTLE_FIRE3_TICK_FLASH_FADE_1:
        BattleFx_FadeOutScreenFlashRamp(2);
        slotPtr->size -= slotPtr->shrinkStep;
        break;
    case BATTLE_FIRE3_TICK_RESET_LEVEL:
        slotPtr->size = slotPtr->startSize;
        break;
    case BATTLE_FIRE3_TICK_SHRINK_2:
        slotPtr->size -= slotPtr->shrinkStep;
        break;
    case BATTLE_FIRE3_TICK_FLASH_START_2:
        BattleFx_StartScreenFlashRamp(1);
        slotPtr->size -= slotPtr->shrinkStep;
        break;
    case BATTLE_FIRE3_TICK_FLASH_FADE_2:
        BattleFx_FadeOutScreenFlashRamp(4);
    case BATTLE_FIRE3_TICK_SHRINK_3:
    case BATTLE_FIRE3_TICK_SHRINK_4:
    case BATTLE_FIRE3_TICK_SHRINK_5:
    case BATTLE_FIRE3_TICK_SHRINK_6:
        slotPtr->size -= slotPtr->shrinkStep;
    }
    (slotPtr->phase)++;
}

/*
 * Spawns shrinking and spinning fire models for Faiga3.
 */
// FUNCTION: FF7 0x0056ea1d
void __cdecl BattleFx_MagicFire3MultiSpawnShrinkingSpinModelsTask(void)
{
    int i6, offsetMax, w, scaleFrac, angleRoll;
    BattleFxFire33SpinModel *selfPtr;
    BattleFaigaShrinkingSpinModel *child;

    selfPtr = (BattleFxFire33SpinModel *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    if (selfPtr->frameCount >= 3 && selfPtr->frameCount <= 0x22) {
        offsetMax = selfPtr->radius;
        scaleFrac = (offsetMax << 0xC) / 0x7D0;
        offsetMax += offsetMax >> 1;
        w = offsetMax << 1;
        for (i6 = 0; i6 < 3; i6++) {
            child = (BattleFaigaShrinkingSpinModel *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicFire3MultiShrinkingSpinModelTask);
            child->pos = selfPtr->pos;
            child->pos.x += (short)(rand() % w - offsetMax);
            child->pos.y += (short)(rand() % w - offsetMax);
            child->pos.z += (short)(rand() % w - offsetMax);
            angleRoll = selfPtr->angle + rand() % 0x1000 + 0x800;
            child->scale = angleRoll * scaleFrac >> 0xC;
            child->scaleStep = child->scale / 6;
        }
        selfPtr->angle += selfPtr->angleStep;
    }
    if (selfPtr->frameCount >= 0x2E) {
        selfPtr->ownerSlot = BATTLE_TASK_FREE;
    }
    (selfPtr->frameCount)++;
}

